# Glossaire MEDINA — chapitre S35 Lésion traumatique de vaisseaux abdominaux (C-01-Cardiologie)
from cardio_1 import a, G

a('REBOA',[('R','Resuscitative (de réanimation)'),('E','Endovascular (endovasculaire)'),('B','Balloon (par ballonnet)'),('O','Occlusion'),('A','of the Aorta (de l’aorte)')],'Resuscitative Endovascular Balloon Occlusion of the Aorta (occlusion aortique endovasculaire de réanimation par ballonnet)',
 '<p>Ballon gonflé dans l’aorte par voie fémorale pour contrôler temporairement une hémorragie du tronc ; non recommandé en routine par l’ESVS 2025.</p>','s35-reboa')
for code,lib in [('S35.0','lésion de l’aorte abdominale'),('S35.1','lésion de la veine cave inférieure'),('S35.2','lésion du tronc cœliaque ou d’une artère mésentérique'),('S35.3','lésion de la veine porte ou de la veine splénique'),('S35.4','lésion des vaisseaux sanguins du rein'),('S35.5','lésion des vaisseaux sanguins iliaques'),('S35.7','lésion de plusieurs vaisseaux de l’abdomen, des lombes et du bassin'),('S35.80','lésion de vaisseaux épiduraux de l’abdomen, des lombes et du bassin'),('S35.81','lésion de vaisseaux sous-duraux de l’abdomen, des lombes et du bassin'),('S35.82','lésion de vaisseaux sous-arachnoïdiens de l’abdomen, des lombes et du bassin'),('S35.88','lésion d’autres vaisseaux de l’abdomen, des lombes et du bassin'),('S35.9','lésion d’un vaisseau non précisé de l’abdomen, des lombes et du bassin')]:
    a(code,[(code,'code de la classification internationale des maladies, '+lib)],lib[0].upper()+lib[1:]+' (CIM-10-GM 2024)','<p>Sous-catégorie de S35, qui code le vaisseau atteint.</p>','s35-codage')
